-- Apply on a new Supabase project. Tenant isolation is enforced by RLS.
create extension if not exists pgcrypto;
create type public.member_role as enum ('owner','admin','manager','chatter','analyst','viewer');
create table public.agencies(id uuid primary key default gen_random_uuid(),name text not null check(length(name) between 2 and 100),created_at timestamptz not null default now());
create table public.agency_members(id uuid primary key default gen_random_uuid(),agency_id uuid not null references public.agencies on delete cascade,user_id uuid not null references auth.users on delete cascade,role public.member_role not null default 'viewer',created_at timestamptz not null default now(),unique(agency_id,user_id));
create index on public.agency_members(user_id,agency_id);
create function public.is_agency_member(a uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.agency_members m where m.agency_id=a and m.user_id=(select auth.uid()))$$;
create function public.has_agency_role(a uuid,roles public.member_role[]) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.agency_members m where m.agency_id=a and m.user_id=(select auth.uid()) and m.role=any(roles))$$;
revoke all on function public.is_agency_member(uuid),public.has_agency_role(uuid,public.member_role[]) from public;
grant execute on function public.is_agency_member(uuid),public.has_agency_role(uuid,public.member_role[]) to authenticated;
create function public.create_agency(agency_name text) returns uuid language plpgsql security definer set search_path='' as $$declare a uuid;begin if auth.uid() is null then raise exception 'unauthenticated';end if;if length(trim(agency_name)) not between 2 and 100 then raise exception 'invalid name';end if;insert into public.agencies(name) values(trim(agency_name)) returning id into a;insert into public.agency_members(agency_id,user_id,role) values(a,auth.uid(),'owner');return a;end$$;
revoke all on function public.create_agency(text) from public;grant execute on function public.create_agency(text) to authenticated;
create table public.creators(id uuid primary key default gen_random_uuid(),agency_id uuid not null references public.agencies on delete cascade,display_name text not null,platform text not null default 'manual',external_ref text,created_at timestamptz not null default now(),unique(agency_id,id));
create table public.fans(id uuid primary key default gen_random_uuid(),agency_id uuid not null references public.agencies on delete cascade,creator_id uuid not null,handle text not null,segment text,notes text,spend_cents bigint not null default 0 check(spend_cents>=0),created_at timestamptz not null default now(),foreign key(agency_id,creator_id) references public.creators(agency_id,id) on delete cascade,unique(agency_id,id));
create table public.conversations(id uuid primary key default gen_random_uuid(),agency_id uuid not null references public.agencies on delete cascade,fan_id uuid not null,status text not null default 'open',assigned_user_id uuid references auth.users,created_at timestamptz not null default now(),foreign key(agency_id,fan_id) references public.fans(agency_id,id) on delete cascade,unique(agency_id,id));
create table public.messages(id uuid primary key default gen_random_uuid(),agency_id uuid not null references public.agencies on delete cascade,conversation_id uuid not null,author_user_id uuid references auth.users,body text not null,kind text not null default 'internal_note',external_message_id text,created_at timestamptz not null default now(),foreign key(agency_id,conversation_id) references public.conversations(agency_id,id) on delete cascade);
create table public.tasks(id uuid primary key default gen_random_uuid(),agency_id uuid not null references public.agencies on delete cascade,title text not null,status text not null default 'todo',assigned_user_id uuid references auth.users,due_at timestamptz,created_at timestamptz not null default now());
create table public.campaigns(id uuid primary key default gen_random_uuid(),agency_id uuid not null references public.agencies on delete cascade,name text not null,channel text not null default 'manual',status text not null default 'draft',cost_cents bigint not null default 0 check(cost_cents>=0),created_at timestamptz not null default now());
create table public.revenue_events(id uuid primary key default gen_random_uuid(),agency_id uuid not null references public.agencies on delete cascade,creator_id uuid not null,fan_id uuid,amount_cents bigint not null check(amount_cents>=0),currency text not null default 'USD',source text not null default 'manual',occurred_at timestamptz not null default now(),foreign key(agency_id,creator_id) references public.creators(agency_id,id),foreign key(agency_id,fan_id) references public.fans(agency_id,id));
create table public.automation_rules(id uuid primary key default gen_random_uuid(),agency_id uuid not null references public.agencies on delete cascade,name text not null,trigger_type text not null,config jsonb not null default '{}'::jsonb,enabled boolean not null default false,created_at timestamptz not null default now());
create table public.audit_logs(id uuid primary key default gen_random_uuid(),agency_id uuid not null references public.agencies on delete cascade,actor_id uuid references auth.users,action text not null,entity_type text not null,entity_id uuid,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index on public.creators(agency_id);create index on public.fans(agency_id,creator_id);create index on public.conversations(agency_id,fan_id);create index on public.messages(agency_id,conversation_id,created_at);create index on public.revenue_events(agency_id,occurred_at);create index on public.tasks(agency_id,status);
-- Membership changes are deliberately service-only until audited invitation endpoints exist.
alter table public.agencies enable row level security;alter table public.agency_members enable row level security;
create policy agency_read on public.agencies for select to authenticated using(public.is_agency_member(id));
create policy member_read on public.agency_members for select to authenticated using(public.is_agency_member(agency_id));
do $$declare t text;begin foreach t in array array['creators','fans','conversations','messages','tasks','campaigns','revenue_events','automation_rules','audit_logs'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy tenant_read on public.%I for select to authenticated using(public.is_agency_member(agency_id))',t);end loop;end$$;
do $$declare t text;begin foreach t in array array['creators','fans','conversations','messages','tasks','campaigns','revenue_events','automation_rules'] loop execute format('create policy tenant_insert on public.%I for insert to authenticated with check(public.has_agency_role(agency_id,array[''owner'',''admin'',''manager'']::public.member_role[]))',t);execute format('create policy tenant_update on public.%I for update to authenticated using(public.has_agency_role(agency_id,array[''owner'',''admin'',''manager'']::public.member_role[])) with check(public.has_agency_role(agency_id,array[''owner'',''admin'',''manager'']::public.member_role[]))',t);execute format('create policy tenant_delete on public.%I for delete to authenticated using(public.has_agency_role(agency_id,array[''owner'',''admin'']::public.member_role[]))',t);end loop;end$$;
-- Disallow tenant-id and ownership reassignment even by authorized managers.
create function public.prevent_tenant_change() returns trigger language plpgsql set search_path='' as $$begin if new.agency_id is distinct from old.agency_id then raise exception 'agency_id immutable';end if;return new;end$$;
do $$declare t text;begin foreach t in array array['creators','fans','conversations','messages','tasks','campaigns','revenue_events','automation_rules'] loop execute format('create trigger immutable_tenant before update on public.%I for each row execute function public.prevent_tenant_change()',t);end loop;end$$;
-- audit_logs are read-only to clients; write them from a privileged audited backend.
